begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table machimoa_review.review_classifications,machimoa_review.review_classification_history,machimoa_review.source_item_content_filters,machimoa_review.source_item_program_facts,machimoa_review.myseoul_residence_reviews,machimoa_review.myseoul_fact_edits in share row exclusive mode;
do $$ declare d text;begin
if machimoa_review.classification_table_metadata('machimoa_review.classification_flow_install') is distinct from '{"acl": "{postgres=arwdDxtm/postgres}", "rls": true, "owner": "postgres", "columns": [["singleton", "boolean", true, "", "", null], ["dirty", "boolean", true, "", "", "false"], ["backup", "jsonb", true, "", "", null]], "indexes": [["machimoa_review.classification_flow_install_pkey", "CREATE UNIQUE INDEX classification_flow_install_pkey ON machimoa_review.classification_flow_install USING btree (singleton)", true]], "forceRls": false, "policies": [], "constraints": [["classification_flow_install_pkey", "PRIMARY KEY (singleton)", true], ["classification_flow_install_singleton_check", "CHECK (singleton)", true]]}'::jsonb or (select encode(sha256(convert_to(backup::text,'UTF8')),'hex') from machimoa_review.classification_flow_install where singleton) is distinct from '331dcd3c04a9320c9c28a37e7b6d898bd2d53a372ff7103ece57a2e9ae17c670' then raise exception 'classification_flow_backup_changed';end if;
if (select dirty from machimoa_review.classification_flow_install where singleton) is distinct from false then raise exception 'classification_flow_records_present';end if;
if to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'a6dbe7e60652dea32953ec8b938c9c2ec69672ffaff518e7059234db686616f7' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'classification_flow_successor_changed';end if;
if to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'e481b55ef165d3a135e2e7a9d0a7ed674c1f72282be3ad6eeb0916f6b16ed250' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'classification_flow_successor_changed';end if;
if to_regprocedure('machimoa_review.classification_flow_dirty()') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_flow_dirty()')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'7afee1cab30c4322a760656ceb1a4d9c640987507859363703b1c2239c61a4d9' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_flow_dirty()')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'classification_flow_successor_changed';end if;
if (select count(*) from pg_trigger where tgname='classification_flow_dirty' and tgfoid='machimoa_review.classification_flow_dirty()'::regprocedure and tgenabled='O' and not tgisinternal and tgtype=28 and tgrelid in ('machimoa_review.review_classifications'::regclass,'machimoa_review.review_classification_history'::regclass,'machimoa_review.source_item_content_filters'::regclass,'machimoa_review.source_item_program_facts'::regclass,'machimoa_review.myseoul_residence_reviews'::regclass,'machimoa_review.myseoul_fact_edits'::regclass))<>6 then raise exception 'classification_flow_trigger_changed';end if;
for d in select value#>>'{}' from machimoa_review.classification_flow_install cross join lateral jsonb_each(backup) loop execute d;end loop;
end $$;
drop trigger classification_flow_dirty on machimoa_review.review_classifications;
drop trigger classification_flow_dirty on machimoa_review.review_classification_history;
drop trigger classification_flow_dirty on machimoa_review.source_item_content_filters;
drop trigger classification_flow_dirty on machimoa_review.source_item_program_facts;
drop trigger classification_flow_dirty on machimoa_review.myseoul_residence_reviews;
drop trigger classification_flow_dirty on machimoa_review.myseoul_fact_edits;
drop function machimoa_review.classification_flow_dirty();
drop table machimoa_review.classification_flow_install;
commit;
